function CompanyTransactions({api}){
 const [filters,setFilters]=useState({from:'',to:'',type:'',party:'',reference:''}),[report,setReport]=useState(null),[message,setMessage]=useState('');const generation=useRef(0),apiRef=useRef(api);useEffect(()=>{apiRef.current=api;},[api]);
 useEffect(()=>{const g=++generation.current;let live=true;const timer=setTimeout(()=>{apiRef.current('/simple-v1/register?'+new URLSearchParams(filters)).then(r=>{if(live&&g===generation.current){setReport(r);setMessage('');}}).catch(e=>{if(live&&g===generation.current){setReport(null);setMessage(e.message);}});},200);return()=>{live=false;clearTimeout(timer);};},[filters]);
 const columns=['Date','Reference','Transaction Type','Client / Vendor / Payee','Particulars','Amount · PKR','Financial Effect','Payment Method','Quantity · bottles'],rows=report?.records.map(r=>[r.date,r.reference,r.type,r.party,r.particulars,r.amount,r.effect,r.method,r.quantity])||[];
 const totals=report?Object.entries({ 'Sales recorded':report.totals.sales,'Return credits':report.totals.returnCredits,'Net sales':report.totals.netSales,'Purchases recorded':report.totals.purchases,'Client payments received':report.totals.clientReceipts,'Vendor payments made':report.totals.vendorPayments,'Business expenses recorded':report.totals.expensesRecorded,'Business expenses paid':report.totals.expensesPaid,'Client receivables':report.clientReceivables,'Vendor payables':report.vendorPayables}):[];
 return <section className="v1-register"><h1>Company Transactions</h1><p>Unique Plastic Industry · PKR. One row per posted business event. Inventory quantities are separate from money.</p><div className="directory-filters no-print">{[['from','From date'],['to','To date'],['party','Client / vendor / payee'],['reference','Reference search']].map(([n,l])=><Label key={n} label={l}><input type={['from','to'].includes(n)?'date':'text'} value={filters[n]} onChange={e=>{setReport(null);setFilters({...filters,[n]:e.target.value});}}/></Label>)}<Label label="Transaction type"><select value={filters.type} onChange={e=>{setReport(null);setFilters({...filters,type:e.target.value});}}><option value="">All types</option>{Object.entries(names).map(([k,n])=><option key={k} value={k}>{n}</option>)}</select></Label></div>{message&&<p role="alert">{message}</p>}{!report&&!message?<p role="status">Loading transactions…</p>:report&&<><p>Filters: {Object.entries(filters).map(([k,v])=>k+': '+(v||'All')).join(' · ')}</p><SummaryCards facts={totals.map(([k,v])=>[k+' · PKR',v])}/><p>Production stock in: {report.productionBottles} bottles.</p><p>{report.balanceCoverage} Unverified party openings: {report.unverifiedParties}.</p><Tools title="Company Transactions" columns={columns} metadata={["Unique Plastic Industry","Company Transaction Register",Object.entries(filters).map(([k,v])=>k+': '+(v||'All')).join(' · '),report.balanceCoverage]} rows={[...rows,...totals.map(([k,v])=>['Summary','',k,'','',v]),['Quantity summary','','Production bottles','','','','','',report.productionBottles]]}/><Table caption="Company Transaction Register · PKR" columns={[...columns,'Details']} rows={rows.map((r,i)=>[...r,<ActionButton onClick={()=>go(root+'/documents/'+report.records[i].id)}>View Details</ActionButton>])}/></>}</section>;
}
